import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };

test('start, query, unknown run', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.start('a'), ok);
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  assert.equal(await h.run('b'), null);
});

test('bad task numbers and moves are refused', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [3, -1, 1.5, NaN]) assert.equal((await h.taskStarted('r', t)).ok, false);
  assert.equal((await h.taskCompleted('r', 0)).ok, false);
  assert.equal((await h.taskRequeued('r', 0)).ok, false);
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('completed only when all complete; evicted counts as in flight', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) assert.deepEqual(await h.taskStarted('r', t), ok);
  assert.equal((await h.run('r')).status, 'running');
  await h.taskCompleted('r', 0);
  await h.taskCompleted('r', 1);
  await h.taskEvicted('r', 2);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'completed', task1: 'completed', task2: 'evicted' });
  await h.taskRequeued('r', 2);
  await h.taskStarted('r', 2);
  assert.deepEqual(await h.taskCompleted('r', 2), ok);
  assert.equal((await h.run('r')).status, 'completed');
  assert.equal((await h.cancel('r')).ok, false);
});

test('all evicted, failure, cancel', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) { await h.taskStarted('r', t); await h.taskEvicted('r', t); }
  assert.equal((await h.run('r')).status, 'evicted');
  await h.taskRequeued('r', 0);
  assert.equal((await h.run('r')).status, 'running');
  await h.start('f');
  await h.taskStarted('f', 1);
  assert.deepEqual(await h.taskFailed('f', 1), ok);
  assert.deepEqual(await h.run('f'), { status: 'failed', task0: 'queued', task1: 'failed', task2: 'queued' });
  assert.deepEqual(await h.taskStarted('f', 0), ok);
  assert.equal((await h.run('f')).status, 'failed');
  await h.start('c');
  await h.taskStarted('c', 0);
  await h.taskCompleted('c', 0);
  assert.deepEqual(await h.cancel('c'), ok);
  assert.deepEqual(await h.run('c'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.start('c')).ok, false);
});

test('retry a failed task', async () => {
  const h = await createHost();
  await h.start('r');
  assert.equal((await h.taskRetried('r', 0)).ok, false);
  await h.taskStarted('r', 0);
  await h.taskFailed('r', 0);
  assert.deepEqual(await h.taskRetried('r', 0), ok);
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  assert.equal((await h.taskRetried('r', 0)).ok, false);
  assert.equal((await h.taskRetried('x', 0)).ok, false);
  // a failed run can be cancelled, stays failed, and the failed task can still be retried
  await h.taskStarted('r', 1);
  await h.taskFailed('r', 1);
  assert.deepEqual(await h.cancel('r'), ok);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'cancelled', task1: 'failed', task2: 'cancelled' });
  assert.deepEqual(await h.taskRetried('r', 1), ok);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'cancelled', task1: 'queued', task2: 'cancelled' });
  await h.taskStarted('r', 1);
  await h.taskCompleted('r', 1);
  assert.equal((await h.run('r')).status, 'cancelled');
  assert.equal((await h.taskRetried('r', 1)).ok, false);
  // all three failed, then retried one by one
  await h.start('a');
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); await h.taskFailed('a', t); }
  assert.equal((await h.run('a')).status, 'failed');
  await h.taskRetried('a', 0);
  assert.equal((await h.run('a')).status, 'failed');
  await h.taskRetried('a', 1);
  await h.taskRetried('a', 2);
  assert.equal((await h.run('a')).status, 'queued');
});

test('cancel one task', async () => {
  const h = await createHost();
  await h.start('r');
  assert.equal((await h.cancelTask('x', 0)).ok, false);
  assert.equal((await h.cancelTask('r', 3)).ok, false);
  assert.deepEqual(await h.cancelTask('r', 0), ok);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'cancelled', task1: 'queued', task2: 'queued' });
  assert.equal((await h.cancelTask('r', 0)).ok, false);
  await h.taskStarted('r', 1);
  await h.taskEvicted('r', 1);
  assert.deepEqual(await h.cancelTask('r', 1), ok);
  await h.taskStarted('r', 2);
  await h.taskCompleted('r', 2);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'completed' });
  assert.equal((await h.taskRetried('r', 0)).ok, false);
  // with a failed task the run stays failed; cancelling every task gives cancelled
  await h.start('f');
  await h.taskStarted('f', 0);
  await h.taskFailed('f', 0);
  assert.deepEqual(await h.cancelTask('f', 1), ok);
  assert.equal((await h.run('f')).status, 'failed');
  assert.equal((await h.cancelTask('f', 0)).ok, false);
  await h.start('c');
  for (const t of [0, 1]) await h.cancelTask('c', t);
  assert.equal((await h.run('c')).status, 'running');
  await h.cancelTask('c', 2);
  assert.deepEqual(await h.run('c'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.start('c')).ok, false);
});

